    "corp_why_4_desc": "Follow attendance, levels and progress for every employee in one place.",
    "corp_cta_title_1": "Let's talk",
    "corp_cta_title_2": "about your team",
    "corp_price_desc": "Pricing depends on the size of your team and what you need. Get in touch and we will put together a quote.",
    "services_slide_1_desc": "Submit a written answer and the AI scores it out of 100, with feedback on what worked, one or two specific corrections and one tip.",
    "services_slide_2_desc": "Multiple-choice, fill-in and word-matching exercises are marked as soon as you answer, with the correct answer and a short explanation of the rule.",
    "services_slide_3_desc": "Your teacher grades your homework with help from AI (score, strengths, what to work on next, an example correction) and sends the feedback to your dashboard.",
    "services_slide_4_desc": "Read the sentence aloud. Speech recognition writes down what you said and shows how many of the expected words it heard.",
    "services_slide_5": "Error Correction",
    "services_slide_5_desc": "Chat with the AI tutor in the language you’re learning. Each message is checked for grammar, vocabulary and spelling, and you see the corrected sentence with a short explanation.",
    "services_slide_6": "Vocabulary Review",
    "services_slide_6_desc": "Words from your teacher’s lesson notes become flashcards. Words you know come back after 1, 3, 7, 14 and 30 days; words you miss come back the next day.",
    "services_slide_7": "Exam Prep",
    "services_slide_7_desc": "Practice tasks in the format of B2 First, C1 Advanced and IELTS (English) and Goethe B1, Goethe B2 and telc B1 (German). Not official exam material; Alimun is not affiliated with the exam boards.",
