    "about_hero_title": "Our story",
    "about_hero_desc": "Built by language teachers who got tired of watching great students stall out in expensive, infrequent 1:1 lessons. Alimun pairs daily live practice with AI feedback so progress happens between classes too, not just during them.",
    "about_btn_waitlist": "Join the waitlist",
    "about_history_title": "A Standard for Real Fluency",
    "about_history_desc": "Built since day one around one idea: a great teacher can guide many students at once if the AI handles the repetitive grading. That belief shapes every tier, every class, and every feature we ship.",
    "about_history_eyebrow": "Our history",
    "about_history_y1_desc": "Alimun founded by language teachers",
    "about_history_y2_desc": "First AI grading engine goes live",
    "about_history_y3_desc": "Private beta with our first 200 learners",
    "about_history_y4_desc": "Public waitlist opens for daily cohorts",
    "about_staff_title": "Meet our teachers",
    "about_staff_1_desc": "With 18 years of teaching, Sarah designs the curriculum behind our Community tier — built so total beginners build a real habit from week one.",
    "about_staff_2_desc": "Jessica brings 22 years of classroom experience, specializing in turning hesitant intermediate speakers into confident, fluent conversationalists.",
    "about_staff_3_desc": "A linguist with 15 years of teaching experience, Martina leads our Micro-Group sessions, known for catching the small mistakes that hold learners back.",
    "about_staff_4_desc": "With 20 years of experience, Kevin leads our Intensive 1:1 program, favored by learners who want a fully custom plan and weekly accountability.",
    "services_hero_title": "Toolkit",
    "services_hero_desc": "Every essay, test, and homework set gets graded the moment you submit it. Practice speaking daily in live classes, then let the AI handle the rest — instant feedback, no waiting for office hours.",
    "services_btn_explore": "Explore Toolkit",
    "services_quote_text": "it's daily feedback and real practice that give every learner a genuine edge.",
