    "corp_tier_1_desc": "Cours collectifs dédiés pour des groupes de 5 à 15 personnes. Idéal pour les services collaborant à l'international.",
    "corp_tier_2_title": "Licence Entreprise",
    "corp_tier_2_desc": "Accès complet à l'organisation avec horaires sur mesure, support prioritaire et facturation flexible.",
    "corp_form_title": "Demande d'information",
    "corp_form_desc": "Parlez-nous des besoins linguistiques de vos équipes et nous vous ferons une proposition sur mesure.",
    "corp_form_company": "Nom de l'entreprise",
