    "corporate_slide_7": "Parlez couramment. Pour la vie. <span class=\"alimun-cta-highlight\">Alimun Corporate</span>.",
    "corporate_form_title": "Demander une démo",
    "corporate_form_desc": "Découvrez comment Alimun peut accélérer l'intégration de vos collaborateurs à l'international.",
