    "corp_huge_slide_2": "94 % der Auslandsberufe scheitern, wenn <span class=\"alimun-cta-highlight\" style=\"background:#ff6565; color:#fff; box-shadow:none;\">die sprachliche Vorbereitung ignoriert wird</span>.",
