    "careers_why_title": "Por que ensinar na Alimun?",
    "careers_why_1_title": "Maior alcance das turmas",
    "careers_why_1_desc": "Chega de repetir a mesma aula particular básica 20 vezes. Ensine um grupo estruturado e deixe a turma interagir.",
    "careers_why_2_title": "Assistente de Correção com IA",
    "careers_why_2_desc": "Nossa IA cuida do vocabulário e dos exercícios de gramática. Você foca na comunicação ao vivo.",
    "careers_why_3_title": "Renda Consistente",
    "careers_why_3_desc": "Receba um pagamento base estável por turma ativa. Seus ganhos aumentam conforme as turmas crescem.",
    "careers_process_title": "Processo de Seleção",
    "careers_process_desc": "Aceitamos menos de 5% dos candidatos para manter nosso padrão de ensino premium.",
    "careers_step_1_title": "Inscrição Online",
    "careers_step_1_desc": "Envie seu currículo, certificados de ensino e um vídeo de introdução curto de 2 minutos.",
    "careers_step_2_title": "Audição Prática",
    "careers_step_2_desc": "Lidere uma sessão de prática de 30 minutos com um pequeno grupo de alunos ativos da Alimun.",
    "careers_step_3_title": "Início da sua turma",
    "careers_step_3_desc": "Conclua a integração, defina seus horários e lance sua primeira turma de conversação oficial.",
    "careers_form_title": "Comece sua Candidatura",
    "careers_form_desc": "Preencha o formulário preliminar para solicitar uma vaga de ensino.",
    "careers_form_language": "Qual idioma você ensina?",
    "careers_form_experience": "Anos de experiência docente",
    "careers_form_video": "Link para o vídeo de apresentação (Loom, YouTube, etc.)",
    "careers_form_submit": "Enviar Candidatura",
    "careers_hero_desc": "Ensine nos seus termos. A Alimun combina turmas de conversação ao vivo com feedback baseado em IA, automatizando todas as correções para que você possa se concentrar totalmente na interação ao vivo com os alunos, mentoria em grupos e prática ativa.",
    "careers_t1_desc": "Desenhar o currículo de turmas na Alimun foi um divisor de águas. Ensino muitos alunos simultaneamente sem me esgotar.",
    "careers_t2_desc": "A IA da Alimun cuida de todos os exercícios de vocabulário e notas. Dedico 100% do meu tempo de aula ao que amo: ajudar os alunos a falar.",
    "careers_t3_desc": "O modelo de turmas de trabalho é muito mais interativo e dinâmico do que repetir aulas individuais o dia todo.",
    "careers_t4_desc": "As taxas consistentes por turma me dão uma excelente estabilidade financeira, mantendo uma agenda totalmente flexível.",
    "careers_cta_ready_title": "Pronto para ensinar?",
    "careers_carousel_1": "Cansado de aulas particulares repetitivas?",
    "careers_carousel_2": "Quer escalar seu impacto?",
    "careers_carousel_3": "Quer uma agenda flexível?",
    "careers_carousel_4": "Ensine na Alimun.",
    "careers_why_4_title": "Horários Flexíveis",
    "careers_why_4_desc": "Defina sua própria disponibilidade e horários de aula. Ensine de qualquer lugar do mundo.",
    "careers_sim_sub_1": "Cansado de <span class=\"alimun-cta-highlight\">não ganhar o suficiente</span> com aulas particulares?",
    "careers_sim_sub_2": "A maioria das plataformas cobra até <span class=\"alimun-cta-highlight\" style=\"background:#ff6565; color:#fff; box-shadow:none;\">33% de comissão</span>.",
    "careers_sim_sub_3": "Na Alimun é <span class=\"alimun-cta-highlight\">30%</span>.",
    "careers_sim_sub_4": "Além disso, nosso modelo permite ensinar até <span class=\"alimun-cta-highlight\">15 alunos</span> de uma vez!",
    "careers_sim_sub_5": "O assistente de IA cuida das correções. <span class=\"alimun-cta-highlight\">Foque em ensinar ao vivo</span>.",
    "careers_sim_sub_6": "Ganhe até <span class=\"alimun-cta-highlight\">€80/hora</span> com total flexibilidade.",
    "careers_sim_sub_7": "Fale fluentemente. Para a vida. <span class=\"alimun-cta-highlight\">Ensine na Alimun</span>.",
    "corporate_hero_title": "soluções corporativas",
    "corporate_hero_desc": "Garanta que seus funcionários transferidos falem com fluência desde o primeiro dia. A Alimun combina turmas profissionais específicas por função com professores nativos experientes e acompanhamento de progresso por IA.",
    "corporate_cta_demo": "Pedir uma demonstração",
    "corporate_why_title": "Fluência da equipa",
    "corporate_why_1_title": "Professores especialistas em expatriação",
    "corporate_why_1_desc": "Especialistas de idioma nativos focados em integração de expatriados, cultura de negócios local e conversação profissional.",
    "corporate_why_2_title": "Turmas específicas por função",
    "corporate_why_2_desc": "Os funcionários aprendem em pequenos grupos organizados por departamento, praticando situações de trabalho realistas.",
    "corporate_why_3_title": "Progresso baseado em IA",
    "corporate_why_3_desc": "O nosso motor de IA automatiza exercícios de vocabulário e avaliações, libertando tempo de conversação com os professores.",
    "corporate_why_4_title": "Painel administrativo de RH",
    "corporate_why_4_desc": "Acompanhe presenças, horas de conversação ativa e marcos do QECR com métricas de desempenho em tempo real.",
    "corporate_process_title": "Como funciona",
    "corporate_step_1_title": "1. Avaliação de competência",
    "corporate_step_1_desc": "Avaliamos os níveis de fala dos funcionários e mapeamos de acordo com os locais de destino.",
